import React from 'react';
import { useNavigate } from 'react-router-dom';
import { TOP_HEADER_PX } from '../config/thoughtspot';

const BLUE  = '#1E5DEB';
const NAVY  = '#071331';
const TEXT  = '#1f2124';
const TEXT2 = '#515962';

// ─── Icons ──────────────────────────────────────────────────────────────────

function IconPulse() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
    </svg>
  );
}

function IconBell() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
      <path d="M13.73 21a2 2 0 0 1-3.46 0" />
    </svg>
  );
}

function IconStar() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
    </svg>
  );
}

// ─── Live alert card ─────────────────────────────────────────────────────────

function LiveAlert({ tag, text, detail, delay }: { tag: string; text: string; detail: string; delay: string }) {
  return (
    <div
      style={{
        display: 'flex', alignItems: 'flex-start', gap: 10,
        padding: '10px 14px',
        backgroundColor: '#FFFFFF',
        borderRadius: 8,
        border: '1px solid rgba(30,93,235,0.12)',
        boxShadow: '0 1px 4px rgba(30,93,235,0.06)',
        animation: 'fadeInUp 0.5s ease both',
        animationDelay: delay,
      }}
    >
      <div style={{ width: 8, height: 8, borderRadius: '50%', backgroundColor: BLUE, marginTop: 5, flexShrink: 0 }} />
      <div>
        <span style={{ display: 'inline-block', fontSize: 10, fontWeight: 600, letterSpacing: '0.06em', textTransform: 'uppercase', color: BLUE, marginBottom: 2 }}>
          {tag}
        </span>
        <p style={{ fontSize: 13, fontWeight: 600, color: TEXT, margin: 0, lineHeight: 1.35 }}>{text}</p>
        <p style={{ fontSize: 12, color: TEXT2, margin: '2px 0 0', lineHeight: 1.4 }}>{detail}</p>
      </div>
    </div>
  );
}

// ─── Feature card ─────────────────────────────────────────────────────────────

function FeatureCard({ icon, title, body, visual }: { icon: React.ReactNode; title: string; body: string; visual?: React.ReactNode }) {
  return (
    <div
      style={{
        flex: '1 1 0', minWidth: 240,
        backgroundColor: '#F4F6FB',
        borderRadius: 12,
        border: '1px solid rgba(30,93,235,0.08)',
        padding: '1.5rem',
        display: 'flex', flexDirection: 'column',
      }}
    >
      <div style={{ flex: 1 }}>
        {visual && <div style={{ marginBottom: '1.25rem' }}>{visual}</div>}
      </div>
      <div>
        <div style={{ marginBottom: 10 }}>{icon}</div>
        <h3 style={{ fontSize: 16, fontWeight: 700, color: NAVY, margin: '0 0 6px', letterSpacing: '-0.02em' }}>{title}</h3>
        <p style={{ fontSize: 13, color: TEXT2, lineHeight: 1.65, margin: 0 }}>{body}</p>
      </div>
    </div>
  );
}

// ─── Stat chip ───────────────────────────────────────────────────────────────

function StatChip({ value, label, icon }: { value: string; label: string; icon: React.ReactNode }) {
  return (
    <div style={{ textAlign: 'center' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, marginBottom: 4 }}>
        {icon}
        <span style={{ fontSize: 36, fontWeight: 800, color: NAVY, letterSpacing: '-0.04em', lineHeight: 1 }}>{value}</span>
      </div>
      <div style={{ fontSize: 13, color: TEXT2, lineHeight: 1.3 }}>{label}</div>
    </div>
  );
}

// ─── Page ────────────────────────────────────────────────────────────────────

export default function HomePage() {
  const navigate = useNavigate();

  return (
    <div style={{ backgroundColor: '#FFFFFF', minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* ── Hero ──────────────────────────────────────────────────────────── */}
      <div style={{ maxWidth: 1100, margin: '0 auto', padding: '4rem 2.5rem 2.5rem' }}>
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: '3rem', flexWrap: 'wrap' }}>

          {/* Left: copy */}
          <div style={{ flex: '1 1 420px', maxWidth: 560 }}>
            <h1
              style={{
                fontSize: 'clamp(36px, 4.5vw, 54px)',
                fontWeight: 800,
                color: TEXT,
                lineHeight: 1.1,
                letterSpacing: '-0.035em',
                margin: '0 0 1.25rem',
              }}
            >
              Supercharge your SAP and eliminate{' '}
              <span style={{ color: BLUE }}>manual rework</span>
            </h1>
            <p style={{ fontSize: 16, color: TEXT2, lineHeight: 1.65, margin: '0 0 2rem', maxWidth: 480 }}>
              Agentic analytics for Accounts Payable, E-Invoicing, and Procurement —
              continuously monitoring your SAP data and pushing proactive alerts before
              exceptions become costly.
            </p>
            <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
              <button
                type="button"
                onClick={() => navigate('/dashboard')}
                style={{
                  display: 'inline-flex', alignItems: 'center', gap: 8,
                  backgroundColor: BLUE, color: '#FFFFFF',
                  border: 'none', padding: '12px 22px', borderRadius: 6,
                  fontSize: 14, fontWeight: 600, cursor: 'pointer', letterSpacing: '-0.01em',
                }}
              >
                Explore your data
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M5 12h14M12 5l7 7-7 7" />
                </svg>
              </button>
              <button
                type="button"
                onClick={() => navigate('/analytics')}
                style={{
                  display: 'inline-flex', alignItems: 'center', gap: 8,
                  backgroundColor: '#FFFFFF', color: TEXT,
                  border: '1.5px solid rgba(0,0,0,0.18)', padding: '12px 22px', borderRadius: 6,
                  fontSize: 14, fontWeight: 600, cursor: 'pointer', letterSpacing: '-0.01em',
                }}
              >
                Ask the Agent
              </button>
            </div>

            {/* Stat row — mirrors xSuite "94% / <1 day / 100%" */}
            <div style={{ display: 'flex', gap: '2rem', marginTop: '2.5rem', flexWrap: 'wrap' }}>
              {[
                { value: '94%', label: 'Touchless processing rate' },
                { value: '<1 day', label: 'Avg. invoice processing time' },
                { value: '100%', label: 'Compliant approvals' },
              ].map(s => (
                <div key={s.value}>
                  <div style={{ fontSize: 26, fontWeight: 800, color: NAVY, letterSpacing: '-0.04em', lineHeight: 1 }}>{s.value}</div>
                  <div style={{ fontSize: 12, color: TEXT2, marginTop: 3 }}>{s.label}</div>
                </div>
              ))}
            </div>
          </div>

          {/* Right: live feed */}
          <div style={{ flex: '0 0 auto', width: 310, display: 'flex', flexDirection: 'column', gap: 8 }}>
            <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: BLUE, marginBottom: 4 }}>
              Live agent feed
            </div>
            <LiveAlert tag="Anomaly · Supplier DE-0421" text="Duplicate invoice detected" detail="INV-8842 matches INV-8801 — same amount, same supplier. Flagged before payment." delay="0.1s" />
            <LiveAlert tag="Recommendation · AP Team" text="Capture cash discount — expires today" detail="€14,200 discount available on Bosch invoice. Approve by 17:00 to capture 2%." delay="0.25s" />
            <LiveAlert tag="Alert · Workflow WF-114" text="Approval stalled for 6 days" detail="PO-matched invoice awaiting sign-off from cost centre manager. Escalation triggered." delay="0.4s" />
          </div>
        </div>
      </div>

      {/* ── Thin blue divider ─────────────────────────────────────────────── */}
      <div style={{ height: 3, background: `linear-gradient(90deg, ${BLUE} 0%, rgba(30,93,235,0.15) 100%)`, maxWidth: 1100, margin: '0 auto 0', borderRadius: 2 }} />

      {/* ── Feature cards ────────────────────────────────────────────────── */}
      <div style={{ backgroundColor: '#F4F6FB', borderTop: '1px solid rgba(30,93,235,0.08)', borderBottom: '1px solid rgba(30,93,235,0.08)' }}>
        <div style={{ maxWidth: 1100, margin: '0 auto', padding: '3rem 2.5rem' }}>
          <div style={{ marginBottom: '2rem' }}>
            <p style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.10em', textTransform: 'uppercase', color: BLUE, margin: '0 0 8px' }}>
              Agentic Analytics
            </p>
          <h2 style={{ fontSize: 28, fontWeight: 800, color: NAVY, letterSpacing: '-0.03em', margin: 0 }}>
            AP automation that actually works — no rework required.
          </h2>
          </div>
          <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
            <FeatureCard
              icon={<IconPulse />}
              title="Live Invoice Monitoring"
              body="Every invoice, approval step, and exception tracked per supplier and cost centre in real time. Full P2P visibility, every second."
              visual={
                <div style={{ height: 100, display: 'flex', alignItems: 'flex-end', gap: 3, paddingBottom: 2 }}>
                  {[55, 72, 60, 88, 65, 92, 78, 84, 70, 95, 80, 68].map((h, i) => (
                    <div key={i} style={{ flex: 1, height: `${h}%`, backgroundColor: i === 10 ? BLUE : `rgba(30,93,235,${0.12 + i * 0.025})`, borderRadius: '2px 2px 0 0' }} />
                  ))}
                </div>
              }
            />
            <FeatureCard
              icon={<IconBell />}
              title="Exception & Anomaly Alerts"
              body="Instant alerts when metrics deviate — duplicate invoices, approval bottlenecks, or payment term breaches. Zero lag between signal and action."
              visual={
                <div style={{ height: 100, position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  {[1, 2, 3].map(i => (
                    <div key={i} style={{ position: 'absolute', width: i * 56, height: i * 56, borderRadius: '50%', border: `1.5px solid rgba(30,93,235,${0.22 - i * 0.05})` }} />
                  ))}
                  <div style={{ width: 10, height: 10, borderRadius: '50%', backgroundColor: BLUE, zIndex: 1 }} />
                </div>
              }
            />
            <FeatureCard
